local({
  female <- as.numeric(carry_within(parent_gender, id, order = wave)) %in% 2
  age <- carry_within(as.numeric(parent_age), id, order = wave) + 0.5
  if_else(female, age + (wave == "follow_up"), NA_real_)
})

local({
  first <- if_else(is.na(firstuse_m), firstuse_y + 0.5, firstuse_y + firstuse_m / 12)
  carried <- carry_within(first, id, order = wave)
  age <- child_age_y + (child_age_m - 1) / 12
  if_else(child_access %in% 0 | (is.na(first) & carried > age), NA_real_, carried)
})

