local({
  ecbq <- sapply(
    list(ecbq_5, ecbq_7, ecbq_8, ecbq_12, ecbq_14, ecbq_15, ecbq_21, ecbq_29, ecbq_30, ecbq_31, ecbq_33, ecbq_38),
    function(x) na_if(as.numeric(x), -3)
  )
  ecbq[, c(4, 5)] <- 4 - ecbq[, c(4, 5)]
  cbq <- sapply(
    list(cbq_3, cbq_6, cbq_9, cbq_12, cbq_15, cbq_18, cbq_21, cbq_24, cbq_27, cbq_30, cbq_33, cbq_36),
    function(x) na_if(as.numeric(x), -3)
  )
  scored <- sapply(list(ecbq, cbq), function(items) {
    score <- rowMeans(items, na.rm = TRUE)
    score[rowSums(!is.na(items)) < ncol(items) / 2] <- NA
    score
  })
  coalesce(scored[, 1], scored[, 2])
})

local({
  items <- cbind(sdq_5, 2 - sdq_7, sdq_12, sdq_18, sdq_22)
  if_else(rowSums(!is.na(items)) >= 3, floor(rowMeans(items, na.rm = TRUE) * 5 + 0.5), NA_real_)
})

