local({
  scored <- sapply(
    list(
      cbind(sdq_3, sdq_8, sdq_13, sdq_16, sdq_24),
      cbind(sdq_5, 2 - sdq_7, sdq_12, sdq_18, sdq_22),
      cbind(sdq_2, sdq_10, sdq_15, 2 - sdq_21, 2 - sdq_25),
      cbind(sdq_6, 2 - sdq_11, 2 - sdq_14, sdq_19, sdq_23)
    ),
    function(items) {
      if_else(rowSums(!is.na(items)) >= 3, floor(rowMeans(items, na.rm = TRUE) * 5 + 0.5), NA_real_)
    }
  )
  rowSums(scored)
})

local({
  height <- coalesce(na_if(as.numeric(bmi_height), -3), na_if(as.numeric(bmi_height_wave2), -3))
  weight <- coalesce(na_if(as.numeric(bmi_weight), -3), na_if(as.numeric(bmi_weight_wave2), -3))
  weight / (height / 100)^2
})
